import {proofStatus} from '/lib/proofs.mjs';
import {createCalculator,supportedFunctions} from '/lib/formulas.mjs';
import {operators,entriesFor,valueOf,runReport,summarize,distribution,reportCSV} from '/lib/reporting.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clientId=sessionStorage.getItem('sheets-client')||crypto.randomUUID();sessionStorage.setItem('sheets-client',clientId);
const uid=()=>crypto.randomUUID(),today=()=>new Date().toISOString().slice(0,10);
let state,revision,workspaceId,sheetId,page='home',view='Table',query='',statusFilter='',sortCol='',sortDir=1,saving=false,selected=new Set(),collapsed=new Set(),month=new Date(),calc;
const app=$('#app'),dialog=$('#dialog');let submitHandler;
let reportId='all-work',dashboardId='workspace-overview',transientReport=null,remoteChanged=false,conflictDraft=null;
let testerName=localStorage.getItem('sheets-tester')||'Tester';
const icons={home:'◈',sheet:'▦',report:'▤',form:'▢',automate:'ϟ',activity:'◷',folder:'▱'};
const button=(label,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const option=(value,label=value,selected=false)=>`<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`;
const field=(label,name,value='',type='text',more='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;
const selectField=(label,name,options,value)=>`<label class="field">${esc(label)}<select name="${name}">${options.map(o=>option(o.value??o,o.label??o,(o.value??o)===value)).join('')}</select></label>`;
const sheet=()=>state.sheets.find(s=>s.id===sheetId),colBy=(s,name)=>s.columns.find(c=>c.name.toLowerCase()===name.toLowerCase());
const val=(s,r,c)=>c?calc.get(s,r,c):'';
const title=(s,r)=>val(s,r,s.columns[0])||'Untitled row';
const depth=(s,r)=>{let n=0,p=r.parentId;while(p&&n<20){n++;p=s.rows.find(x=>x.id===p)?.parentId;}return n;};
const color=v=>/complete|done/i.test(v)?'green':/progress/i.test(v)?'blue':/review/i.test(v)?'amber':/high/i.test(v)?'rose':'gray';
const badge=v=>`<span class="badge ${color(String(v))}">${esc(v||'—')}</span>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function modal(title,body,handler,submit='Save'){dialog.classList.remove('wide-dialog','row-inspector');dialog.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${esc(title)}</h2><button type="button" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${esc(submit)}</button></div></form>`;submitHandler=handler;dialog.showModal();}
dialog.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const ok=await submitHandler(f);if(ok!==false)dialog.close();}catch(e){toast(e.message);}});
async function request(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Sheets-Tester':testerName,'X-Sheets-Client':clientId},body:JSON.stringify(body)});const x=await r.json();if(!r.ok){const error=Error(x.error);error.status=r.status;throw error;}return x;}
async function mutate(label,fn){if(saving){toast('Please wait for the current change to save.');return false;}const next=structuredClone(state);fn(next);saving=true;$('#save-status')?.classList.add('busy');try{const x=await request('/api/state',{state:next,revision,label});state=x.state;revision=x.revision;remoteChanged=false;conflictDraft=null;const active=document.activeElement;const focus=active?.classList.contains('cell-input')?{row:active.dataset.row,col:active.dataset.col}:null;render();if(focus){document.querySelector(`.cell-input[data-row="${CSS.escape(focus.row)}"][data-col="${CSS.escape(focus.col)}"]`)?.focus();}return true;}catch(e){if(e.status===409){conflictDraft=next;notifyRemoteChange();}toast(e.message);return false;}finally{saving=false;$('#save-status')?.classList.remove('busy');}}
function blankRow(s,cells={}){return {id:uid(),parentId:null,cells:Object.fromEntries(s.columns.map(c=>[c.id,cells[c.id]??(c.type==='checkbox'?false:'')])),comments:[],attachments:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
function visibleRows(s){let rows=s.rows.filter(r=>{if(query&&!s.columns.some(c=>String(val(s,r,c)).toLowerCase().includes(query.toLowerCase())))return false;const sc=colBy(s,'Status');if(statusFilter&&String(val(s,r,sc))!==statusFilter)return false;if(!query&&!statusFilter){let p=r.parentId;while(p){if(collapsed.has(p))return false;p=s.rows.find(x=>x.id===p)?.parentId;}}return true;});if(sortCol){const c=s.columns.find(c=>c.id===sortCol);if(c)rows.sort((a,b)=>String(val(s,a,c)).localeCompare(String(val(s,b,c)),undefined,{numeric:true})*sortDir);}return rows;}
function sheetPage(){const s=sheet();if(!s)return empty('A fresh start','Create your first sheet to organize your work.','Create sheet','new-sheet');const rows=visibleRows(s),sc=colBy(s,'Status');return `<section class="sheet-heading"><div><div class="eyebrow">WORKSPACE SHEET</div><h1>${esc(s.name)} ${button('···','sheet-settings','aria-label="Sheet settings"','more')}</h1><p>${esc(s.description||'A shared place for every detail.')}</p></div><div class="heading-actions">${button(icon('download',15)+' Export','export-menu')}${button(icon('plus',15)+' Add row','add-row','','primary')}</div></section><div class="view-tabs">${['Table','Board','Calendar','Gantt','Timeline','Dashboard'].map(v=>`<button data-action="view" data-view="${v}" class="${view===v?'selected':''}">${icon({Table:'sheet',Board:'board',Calendar:'calendar',Gantt:'gantt',Timeline:'timeline',Dashboard:'dashboards'}[v],16)}${v}</button>`).join('')}<span class="tab-spacer"></span><span class="row-count">${s.rows.length} rows · ${s.columns.length} columns</span></div><div class="toolbar"><div class="search-wrap">${icon('search',15)} <input id="search" value="${esc(query)}" placeholder="Find in this sheet…" aria-label="Search sheet"></div><select id="status-filter" aria-label="Filter by status">${option('','All statuses')}${(sc?.options||[]).map(v=>option(v,v,statusFilter===v)).join('')}</select>${button('⇅ Sort','sort')}${button('ƒx Formulas','formula-help')}${button('＋ Column','new-column')}${button(icon('settings',14)+' View options','view-options')}<span class="tab-spacer"></span>${selected.size?`${button('Indent','indent')}${button('Outdent','outdent')}${button(`Delete ${selected.size}`,'delete-rows','','danger')}`:''}${button('⋯','sheet-tools','aria-label="More sheet tools"')}</div>${view==='Table'?grid(s,rows):view==='Board'?board(s,rows):view==='Calendar'?calendar(s,rows):view==='Dashboard'?dashboard(s):timeline(s,rows)}<div class="sheet-footer"><span><span class="live-dot"></span> ${rows.length} visible rows</span><span>${view==='Table'?'Click a cell to edit · Enter a formula starting with = · Select rows to group work':'All views use the same sheet data'}</span></div>`;}
function grid(s,rows){const cols=s.columns.filter(c=>!c.hidden);return `<div class="grid-scroll"><table class="grid"><thead><tr><th class="row-select"><input type="checkbox" id="select-all" aria-label="Select all visible rows" ${rows.length&&rows.every(r=>selected.has(r.id))?'checked':''}></th><th class="row-num">#</th><th class="row-tools-head" aria-label="Row tools"><span title="Attachments">${rowIcon('attachment')}</span><span title="Comments">${rowIcon('comment')}</span><span title="Proofing and review">${rowIcon('proof')}</span></th>${cols.map(c=>`<th style="min-width:${c.width||150}px"><button data-action="edit-column" data-id="${c.id}"><span class="column-icon">${{text:'T',number:'#',select:'⌄',date:'▦',checkbox:'☑',contact:'@'}[c.type]||'T'}</span>${esc(c.name)} ${c.formula?'<span class="fx">ƒx</span>':''}<span class="column-menu">⌄</span></button></th>`).join('')}<th class="row-detail"></th></tr></thead><tbody>${rows.map(r=>`<tr class="${selected.has(r.id)?'row-selected':''}"><td class="row-select"><input class="row-check" data-row="${r.id}" type="checkbox" aria-label="Select ${esc(title(s,r))}" ${selected.has(r.id)?'checked':''}></td><td class="row-num">${s.rows.indexOf(r)+1}</td><td class="row-tools-cell">${rowTools(s,r)}</td>${cols.map((c,i)=>`<td class="cell ${c.formula?'calculated':''}" ${c.type==='select'?`data-tone="${color(String(val(s,r,c)))}"`:''}><div class="cell-inner" style="${i===0?`padding-left:${depth(s,r)*18+5}px`:''}">${i===0&&s.rows.some(x=>x.parentId===r.id)?button(collapsed.has(r.id)?'▸':'▾','collapse',`data-id="${r.id}" aria-label="Toggle children"`,'collapse'):''}${editor(s,r,c)}</div></td>`).join('')}<td>${button('↗','row-detail',`data-id="${r.id}" aria-label="Open row details"`,'row-open')}${r.comments?.length?'<span class="comment-dot"></span>':''}</td></tr>`).join('')}</tbody></table>${rows.length?'':`<div class="empty-inline">No rows match this view.</div>`}<button class="add-row-bottom" data-action="add-row">＋ Add a row</button></div>`;}
function editor(s,r,c){const v=val(s,r,c),attrs=`data-row="${r.id}" data-col="${c.id}" aria-label="${esc(c.name)} for ${esc(title(s,r))}"`;if(c.formula)return `<span class="formula-value ${String(v).startsWith('#')?'error-value':''}" title="${esc(c.formula)}">${esc(v)}</span>`;if(c.type==='checkbox')return `<input class="cell-input checkbox" type="checkbox" ${attrs} ${v===true?'checked':''}>`;if(c.type==='select')return `<select class="cell-input" ${attrs}>${option('','—')}${(c.options||[]).map(x=>option(x,x,x===v)).join('')}</select>`;return `<input class="cell-input" ${attrs} type="${c.type==='date'&&!(typeof r.cells[c.id]==='string'&&r.cells[c.id].startsWith('='))?'date':'text'}" value="${esc(v)}" data-raw="${esc(r.cells[c.id]??'')}" ${c.type==='number'?'inputmode="decimal"':''}>`;}
function card(s,r){return `<article class="task-card" draggable="true" data-drag-row="${r.id}" data-action="row-detail" data-id="${r.id}" tabindex="0" role="button"><div class="card-top">${badge(val(s,r,colBy(s,'Priority')))}<span>···</span></div><h3>${esc(title(s,r))}</h3><p>${esc(val(s,r,colBy(s,'Owner'))||'Unassigned')}</p><div class="card-bottom"><span>▦ ${esc(val(s,r,colBy(s,'Due'))||'No due date')}</span><span>${r.comments?.length?'◌ '+r.comments.length:''}</span></div></article>`;}
function board(s,rows){const c=s.columns.find(c=>c.id===s.viewConfig?.boardColumnId)||colBy(s,'Status')||s.columns.find(c=>c.type==='select');if(!c)return empty('Give your work a flow','Add a dropdown column to organize cards into lanes.','Add column','new-column');const lanes=[...new Set([...(c.options||[]),...rows.map(r=>String(val(s,r,c))), ''])];return `<div class="board">${lanes.map(l=>{const rr=rows.filter(r=>String(val(s,r,c))===l);return `<section class="lane" data-lane="${esc(l)}" data-column="${c.id}"><div class="lane-head"><span class="lane-dot ${color(l)}"></span><h3>${esc(l||'Unassigned')}</h3><span>${rr.length}</span>${button('+','add-row',`data-lane="${esc(l)}" data-column="${c.id}" aria-label="Add card"`)}</div>${rr.map(r=>card(s,r)).join('')}</section>`;}).join('')}</div>`;}
function calendar(s,rows){const c=s.columns.find(c=>c.id===s.viewConfig?.dateColumnId)||colBy(s,'Due')||s.columns.find(c=>c.type==='date');if(!c)return empty('Put work on the calendar','Add a date column to see your schedule.','Add column','new-column');const start=new Date(month.getFullYear(),month.getMonth(),1),offset=start.getDay(),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return `<div class="calendar"><div class="calendar-nav"><h2>${month.toLocaleString(undefined,{month:'long',year:'numeric'})}</h2><div>${button('←','month-prev')}${button('Today','month-today')}${button('→','month-next')}</div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="day-name">${d}</div>`).join('')}${Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const n=i-offset+1,key=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;return `<div class="day ${n<1||n>days?'muted-day':''} ${key===today()?'today':''}">${n>0&&n<=days?`<span class="day-number">${n}</span>${rows.filter(r=>val(s,r,c)===key).map(r=>`<button class="calendar-event" data-action="row-detail" data-id="${r.id}">${esc(title(s,r))}</button>`).join('')}`:''}</div>`;}).join('')}</div></div>`;}
function timeline(s,rows){const startC=s.columns.find(c=>c.id===s.viewConfig?.startColumnId)||colBy(s,'Start')||s.columns.find(c=>c.type==='date'),endC=s.columns.find(c=>c.id===s.viewConfig?.endColumnId)||colBy(s,'Due')||s.columns.filter(c=>c.type==='date')[1];if(!startC||!endC)return empty('See the bigger picture','Add Start and Due date columns to build a timeline.','Add column','new-column');const rr=rows.filter(r=>val(s,r,startC)&&val(s,r,endC));const stamps=rr.flatMap(r=>[Date.parse(val(s,r,startC)),Date.parse(val(s,r,endC))]).filter(Number.isFinite);const min=stamps.length?Math.min(...stamps):Date.now(),max=stamps.length?Math.max(...stamps):min+14*864e5,span=Math.max(7,(max-min)/864e5+2);return `<div class="timeline"><div class="timeline-note">${view==='Gantt'?'Date-range Gantt':'Timeline'} · Edit dates in the table to reschedule. Dependency scheduling is on the roadmap.</div><div class="timeline-head"><span>Task</span><div>${Array.from({length:Math.min(10,Math.ceil(span))},(_,i)=>`<span>${new Date(min+i*span/Math.min(10,Math.ceil(span))*864e5).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>`).join('')}</div></div>${rr.map(r=>{const a=Date.parse(val(s,r,startC)),b=Date.parse(val(s,r,endC));return `<div class="timeline-row"><button data-action="row-detail" data-id="${r.id}" style="padding-left:${depth(s,r)*16+16}px">${esc(title(s,r))}</button><div class="timeline-track"><button class="gantt-bar ${color(String(val(s,r,colBy(s,'Status'))))}" data-action="row-detail" data-id="${r.id}" style="left:${(a-min)/864e5/span*100}%;width:${Math.max(1,(b-a)/864e5+1)/span*100}%" title="${esc(title(s,r))}: ${esc(val(s,r,startC))} – ${esc(val(s,r,endC))}">${esc(title(s,r))}</button></div></div>`;}).join('')}${rr.length?'':'<p class="empty-inline">Add dates to your rows to see them here.</p>'}</div>`;}
const metric=(label,value,note,cls='')=>`<article class="metric ${cls}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;
const empty=(title,body,label,action)=>`<section class="empty"><span class="empty-icon">▦</span><h2>${esc(title)}</h2><p>${esc(body)}</p>${button(label,action,'','primary')}</section>`;
function pageHeader(kicker,title,description,actions=''){return `<section class="sheet-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></section>`;}
function formsPage(){const ss=state.sheets.filter(s=>s.workspaceId===workspaceId);return pageHeader('LESS CHASING. MORE DOING.','Forms','Collect structured information directly into your sheets.',button('+ Create form','new-form','','primary'))+`<div class="page-body sheet-cards">${ss.flatMap(s=>(s.forms||[]).map(f=>`<article class="panel"><span class="eyebrow">${esc(s.name)}</span><h2>${esc(f.name)}</h2><p>${esc(f.description||'Add a new submission to this sheet.')}</p><div class="action-row">${button('Open form','open-form',`data-sheet="${s.id}" data-id="${f.id}"`,'primary')}${button('Edit','edit-form',`data-sheet="${s.id}" data-id="${f.id}"`)}${button('Delete','delete-form',`data-sheet="${s.id}" data-id="${f.id}"`)}</div><small>Local form · ${f.columnIds.length} fields</small></article>`)).join('')||empty('Turn requests into rows','Build a local intake form from your sheet columns.','Create form','new-form')}</div>`;}
function automationsPage(){const ss=state.sheets.filter(s=>s.workspaceId===workspaceId);return pageHeader('LET THE SMALL THINGS TAKE CARE OF THEMSELVES','Automations','When a cell changes to a value, update another cell in the row.',button('+ New workflow','new-automation','','primary'))+`<div class="page-body">${ss.flatMap(s=>(s.automations||[]).map(a=>`<section class="panel automation"><span class="automation-icon">ϟ</span><div><h3>${esc(a.name)}</h3><p>${esc(s.name)} · When ${esc(s.columns.find(c=>c.id===a.columnId)?.name)} becomes “${esc(a.equals)}” → set ${esc(s.columns.find(c=>c.id===a.targetColumnId)?.name)} to “${esc(a.value)}”</p></div>${button(a.enabled===false?'Enable':'Pause','toggle-automation',`data-sheet="${s.id}" data-id="${a.id}"`)}${button('Delete','delete-automation',`data-sheet="${s.id}" data-id="${a.id}"`)}</section>`)).join('')||empty('Make work flow','Create your first cell-change workflow.','New workflow','new-automation')}<p class="muted">Rules run when edits are saved. Scheduled jobs, email notifications, and multi-step workflows are not yet implemented.</p></div>`;}
function activityPage(){return pageHeader('EVERY CHANGE HAS A STORY','Activity','A local history of changes across your workspaces.')+`<div class="page-body"><section class="panel">${[...(state.activity||[])].reverse().map(a=>`<div class="activity-row"><span class="activity-dot"></span><span>${esc(a.message)}</span><time>${esc(a.by||'Local')} · ${new Date(a.at).toLocaleString()}</time></div>`).join('')||'<p>Your activity will appear here as you work.</p>'}</section></div>`;}
async function editCell(el){const s=sheet(),r=s.rows.find(r=>r.id===el.dataset.row),c=s.columns.find(c=>c.id===el.dataset.col);if(!r||!c)return;let v=el.type==='checkbox'?el.checked:el.value;if(c.type==='number'&&v!==''&&!String(v).startsWith('=')){if(!Number.isFinite(Number(v))){toast('Enter a number or a formula.');return;}v=Number(v);}await mutate(`Edited ${c.name} in ${s.name}`,n=>{const rr=n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id);rr.cells[c.id]=v;rr.updatedAt=new Date().toISOString();});}
function columnModal(existing){const s=sheet();modal(existing?'Edit column':'Add column',field('Column name','name',existing?.name||'','text','required maxlength="80"')+selectField('Type','type',['text','number','select','date','checkbox','contact'],existing?.type||'text')+field('Column width (pixels)','width',existing?.width||160,'number','min=80 max=600 step=10')+field('Dropdown choices (comma separated)','options',existing?.options?.join(', ')||'')+field('Column formula (optional)','formula',existing?.formula||'')+'<p class="hint">Example: =[Budget]@row - [Spent]@row. Column formulas apply to every row. Renaming a referenced column requires updating its formulas.</p>'+(existing&&s.columns[0].id!==existing.id?`<div class="action-row">${button('Move left','move-column',`data-id="${existing.id}" data-direction="-1"`)}${button('Move right','move-column',`data-id="${existing.id}" data-direction="1"`)}${button('Delete column','delete-column',`data-id="${existing.id}"`,'danger')}</div>`:''),f=>{if(s.columns.some(c=>c.id!==existing?.id&&c.name.toLowerCase()===f.name.trim().toLowerCase()))throw Error('Use a unique column name.');return mutate(`${existing?'Updated':'Added'} column ${f.name}`,n=>{const sh=n.sheets.find(x=>x.id===s.id);const c={id:existing?.id||uid(),name:f.name.trim(),type:f.type,width:Math.max(80,Math.min(600,Number(f.width)||160)),hidden:existing?.hidden||false,options:f.options.split(',').map(x=>x.trim()).filter(Boolean),formula:f.formula.trim()?f.formula.trim().replace(/^=?/,'='):''};if(existing)sh.columns[sh.columns.findIndex(x=>x.id===existing.id)]=c;else sh.columns.push(c);});});}
function rowModal(id){const s=sheet(),r=s.rows.find(r=>r.id===id);modal(title(s,r),`<div class="detail-fields">${s.columns.map(c=>c.formula?`<label class="field">${esc(c.name)}<div class="readonly">${esc(val(s,r,c))}<small>${esc(c.formula)}</small></div></label>`:c.type==='select'?selectField(c.name,c.id,['',...(c.options||[])],r.cells[c.id]):c.type==='checkbox'?`<label class="check-field"><input name="${c.id}" type="checkbox" ${r.cells[c.id]?'checked':''}> ${esc(c.name)}</label>`:field(c.name,c.id,r.cells[c.id],c.type==='date'?'date':'text')).join('')}</div><hr><h3>Conversation</h3>${(r.comments||[]).map(c=>`<div class="comment"><b>${esc(c.by||'Tester')}</b><time>${new Date(c.at).toLocaleString()}</time><p>${esc(c.text)}</p></div>`).join('')||'<p class="hint">Keep notes and decisions with the work.</p>'}<label class="field">Add a comment<textarea name="comment" placeholder="Leave a note…"></textarea></label><h3>Attachments</h3>${(r.attachments||[]).map(a=>`<div class="attachment"><span>${esc(a.name)}</span>${button('Download','download-attachment',`data-row="${r.id}" data-id="${a.id}"`)}${button('Remove','remove-attachment',`data-row="${r.id}" data-id="${a.id}"`)}</div>`).join('')}<label class="field">Attach a file (up to 2 MB)<input type="file" id="attachment-input"></label>`,async f=>{let attachment;const file=$('#attachment-input').files[0];if(file){if(file.size>2*1024*1024)throw Error('Attachment limit is 2 MB per file.');attachment={id:uid(),name:file.name,type:file.type,data:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);})};}return mutate(`Updated row in ${s.name}`,n=>{const rr=n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id);for(const c of s.columns)if(!c.formula){const v=c.type==='checkbox'?f[c.id]==='on':f[c.id]??'';rr.cells[c.id]=c.type==='number'&&v!==''&&!String(v).startsWith('=')?Number(v):v;}rr.comments||=[];if(f.comment.trim())rr.comments.push({id:uid(),text:f.comment.trim(),by:testerName,at:new Date().toISOString()});rr.attachments||=[];if(attachment)rr.attachments.push(attachment);rr.updatedAt=new Date().toISOString();});});}
function download(name,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function parseCSV(text){let rows=[],row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(v);v='';}else if(ch==='\n'&&!quoted){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v='';}else v+=ch;}if(quoted)throw Error('Unclosed CSV quote');if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row);}return rows;}
function importModal(){modal('Import data',selectField('Import type','kind',[{value:'csv',label:'CSV → new sheet'},{value:'json',label:'Project backup → replace local project'}],'csv')+'<label class="field">File<input id="import-file" type="file" accept=".csv,.json" required></label><p class="hint">CSV imports values as text. Project restore replaces all local workspaces and can be undone.</p>',async f=>{const file=$('#import-file').files[0];if(!file)return false;const text=await file.text();if(f.kind==='json'){const imported=JSON.parse(text);return mutate('Restored project backup',n=>Object.assign(n,imported.state||imported));}const [headers,...rows]=parseCSV(text);if(!headers?.length)throw Error('CSV has no columns');const names=new Set();const columns=headers.map((h,i)=>{let name=h.trim()||`Column ${i+1}`;while(names.has(name))name+=' (2)';names.add(name);return {id:uid(),name,type:'text',options:[],formula:''};});const sh={id:uid(),workspaceId,folderId:null,name:file.name.replace(/\.csv$/i,''),description:'Imported from CSV',columns,rows:[],automations:[],forms:[],createdAt:new Date().toISOString()};sh.rows=rows.filter(a=>a.some(v=>v!=='')).map(a=>blankRow(sh,Object.fromEntries(columns.map((c,i)=>[c.id,a[i]??'']))));const ok=await mutate('Imported CSV',n=>n.sheets.push(sh));if(ok){sheetId=sh.id;page='sheet';view='Table';render();}return ok;},'Import');}
