const icon=(name,size=18)=>`<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.sheet}</svg>`;
const monochrome=['#171717','#707070','#b0b0b0','#d7d7d7','#eeeeee'];
function statusGradient(items,total){if(!total)return '#ededed';let start=0;return 'conic-gradient('+items.map((item,i)=>{const end=start+item.count/total*100;const segment=monochrome[i%monochrome.length]+' '+start+'% '+end+'%';start=end;return segment;}).join(',')+')';}
const fmt=n=>new Intl.NumberFormat(undefined,{maximumFractionDigits:1}).format(n||0);
const relativeDate=v=>v?new Date(v+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No date';
const currentSheets=()=>state.sheets.filter(s=>s.workspaceId===workspaceId);
const sourceFields=()=>[...new Set(currentSheets().flatMap(s=>s.columns.map(c=>c.name)))];
const sourceChecks=(ids,prefix='source')=>`<div class="source-checks">${currentSheets().map(s=>`<label class="check-field"><input type="checkbox" name="${prefix}-${s.id}" ${ids.includes(s.id)?'checked':''}>${icon('sheet',15)}<span>${esc(s.name)}</span><small>${s.rows.length} rows</small></label>`).join('')}</div>`;

function render(){
 calc=createCalculator(state);state.dashboards||=[];state.feedback||=[];state.testing||={};
 if(!state.workspaces.some(w=>w.id===workspaceId))workspaceId=state.workspaces[0]?.id;
 if(!sheet())sheetId=state.sheets.find(s=>s.workspaceId===workspaceId)?.id;
 const ws=state.workspaces.find(w=>w.id===workspaceId),sheets=currentSheets();
 const navSheet=s=>`<button class="nav-sheet ${page==='sheet'&&s.id===sheetId?'active':''}" data-action="sheet" data-id="${s.id}">${icon('sheet',16)}<span>${esc(s.name)}</span></button>`;
 const content=page==='sheet'?sheetPage():page==='home'?homePage():page==='reports'?reportsPage():page==='dashboards'?dashboardsPage():page==='forms'?formsPage():page==='automations'?automationsPage():page==='testing'?testingPage():activityPage();
 app.innerHTML=`<aside class="sidebar"><button class="brand" data-action="page" data-page="home" aria-label="sheets home"><span class="brand-symbol">${icon('sheet',23)}</span>sheets<span class="beta-label">BETA</span></button>
 <button class="workspace-switch" data-action="workspace-settings"><span class="workspace-avatar">${esc((ws?.name||'W')[0])}</span><span>${esc(ws?.name||'Workspace')}<small>Local workspace</small></span>${icon('chevron',15)}</button>
 <select class="workspace-picker" aria-label="Select workspace" id="workspace-picker">${state.workspaces.map(w=>option(w.id,w.name,w.id===workspaceId)).join('')}</select>
 <nav>${[['home','Overview'],['reports','Reports'],['dashboards','Dashboards'],['forms','Forms'],['automations','Automations']].map(([p,n])=>`<button class="nav-item ${page===p?'active':''}" data-action="page" data-page="${p}" aria-label="${n}">${icon(p)}<span>${n}</span>${p==='reports'&&state.reports.length?`<small>${state.reports.filter(r=>r.workspaceId===workspaceId).length}</small>`:''}</button>`).join('')}</nav>
 <div class="section-label">WORKSPACE ${button(icon('plus',15),'new-sheet','aria-label="Create sheet"')}</div><div class="sheet-tree">${sheets.filter(s=>!s.folderId).map(navSheet).join('')}${state.folders.filter(f=>f.workspaceId===workspaceId).map(f=>`<div class="folder-label">${icon('folder',15)} ${esc(f.name)} ${button(icon('more',14),'folder-settings',`data-id="${f.id}" aria-label="Folder options"`)}</div><div class="folder-children">${sheets.filter(s=>s.folderId===f.id).map(navSheet).join('')}</div>`).join('')}${button(icon('plus',14)+' New folder','new-folder','','text-button')}</div>
 <div class="sidebar-bottom">${[['testing','Test lab'],['activity','Activity']].map(([p,label])=>`<button class="nav-item ${page===p?'active':''}" data-action="page" data-page="${p}" aria-label="${label}">${icon(p)}<span>${label}</span></button>`).join('')}<button class="profile-button" data-action="tester-profile"><span class="avatar">${esc(testerName.slice(0,2).toUpperCase())}</span><span>${esc(testerName)}<small>Testing on this Mac</small></span>${icon('more',16)}</button></div></aside>
 <main><header class="topbar"><div class="breadcrumbs">${icon('folder',14)} ${esc(ws?.name)} <span>/</span> <b>${esc(page==='sheet'?(sheet()?.name||'Sheets'):page==='testing'?'Test lab':page[0].toUpperCase()+page.slice(1))}</b></div><div class="top-actions"><span id="save-status">${icon('check',13)} All changes saved</span>${button(icon('undo',16),'undo','title="Undo your last change" aria-label="Undo last change"')}${button(icon('search',17),'command','title="Find anything (⌘K)" aria-label="Find anything"')}${button('Help','help')}</div></header>${remoteChanged?syncBanner():''}<div id="content" class="page-${page}">${content}</div></main>`;
 localStorage.setItem('sheets-location',JSON.stringify({page,workspaceId,sheetId,view,reportId,dashboardId}));
}

function defaultReport(){return {id:'all-work',name:'All work',description:'A complete picture, without switching between sheets.',sheetIds:currentSheets().map(s=>s.id),columns:['$task','$sheet','Status','Owner','Due'],filters:[],groupBy:'$sheet',sortBy:'Due'};}
function activeReport(){if(transientReport)return transientReport;if(reportId==='all-work')return defaultReport();return state.reports.find(r=>r.id===reportId)||state.reports.find(r=>r.workspaceId===workspaceId)||defaultReport();}
function reportsPage(){
 const saved=state.reports.filter(r=>r.workspaceId===workspaceId),r=activeReport(),result=runReport(state,r),summary=summarize(result.rows),columns=r.columns||['$task','$sheet','Status','Owner','Due'];
 return pageHeader('SEE WHAT MATTERS','Reports','Less searching. More perspective.',button(icon('plus',15)+' New report','new-report','','primary'))+
 `<div class="report-layout"><aside class="report-library"><div class="library-label">YOUR REPORTS <span>${saved.length+1}</span></div>${[defaultReport(),...saved].map(x=>`<button class="report-link ${x.id===r.id?'active':''}" data-action="select-report" data-id="${x.id}"><span class="report-link-icon">${icon('reports',17)}</span><span><b>${esc(x.name)}</b><small>${x.sheetIds.length} source sheet${x.sheetIds.length===1?'':'s'}</small></span>${icon('chevron',14)}</button>`).join('')}<div class="library-tip">${icon('link',18)}<p>Always connected.<br>Reports show the latest values from your sheets.</p></div></aside>
 <section class="report-workspace"><div class="report-title"><div class="report-emblem">${icon('reports',24)}</div><div><h2>${esc(r.name)}</h2><p>${esc(r.description||'Your work, brought into focus.')}</p></div><div class="action-row">${button(icon('download',15)+' Export','export-report')}${button(icon('settings',15)+' Configure','configure-report')}</div></div>
 <div class="report-summary">${[['Matched items',summary.total],['Completed',summary.complete],['Open',summary.open],['Overdue',summary.overdue]].map(([l,n])=>`<div><span>${l}</span><strong>${fmt(n)}</strong></div>`).join('')}</div>
 <div class="report-query"><span>${icon('link',14)} ${r.sheetIds.length} source sheet${r.sheetIds.length===1?'':'s'}</span>${(r.filters||[]).map(f=>`<span class="query-chip">${esc(f.column)} ${esc(operators.find(o=>o[0]===f.operator)?.[1]||f.operator)} ${esc(f.value)}</span>`).join('')}${r.groupBy?`<span class="query-chip">Grouped by ${esc(r.groupBy==='$sheet'?'source sheet':r.groupBy)}</span>`:''}<span class="tab-spacer"></span><span>Live results</span></div>
 <div class="report-results">${result.groups.map(g=>`<div class="report-group"><div class="group-heading">${icon('chevron',15)} ${esc(g.name)} <span>${g.rows.length}</span></div><table class="report-table"><thead><tr>${columns.map(c=>`<th>${esc(c==='$task'?'Item':c==='$sheet'?'Source sheet':c)}</th>`).join('')}<th></th></tr></thead><tbody>${g.rows.map(e=>`<tr>${columns.map((c,i)=>`<td>${i===0?`<button class="report-item-link" data-action="report-row" data-sheet="${e.sheetId}" data-id="${e.rowId}">${esc(valueOf(e,c))||'—'}</button>`:c.toLowerCase()==='status'||c.toLowerCase()==='priority'?badge(valueOf(e,c)):esc(valueOf(e,c))||'<span class="muted">—</span>'}</td>`).join('')}<td>${button(icon('arrow',15),'report-row',`data-sheet="${e.sheetId}" data-id="${e.rowId}" aria-label="Open ${esc(e.title)}"`,'icon-button')}</td></tr>`).join('')}</tbody></table></div>`).join('')||`<div class="empty"><span class="empty-icon">${icon('search',32)}</span><h2>No matching work</h2><p>Adjust the conditions or choose a different source sheet.</p>${button('Edit report','configure-report')}</div>`}</div><div class="report-bottom">${result.rows.length} items · Values update when source sheets change. ${saved.some(x=>x.id===r.id)?button('Delete report','delete-report',`data-id="${r.id}"`,'text-button'):''}</div></section></div>`;
}

function filterRow(f={column:'Status',operator:'equals',value:''}){return `<div class="filter-builder-row"><select class="filter-column" aria-label="Filter column">${sourceFields().map(c=>option(c,c,c===f.column)).join('')}</select><select class="filter-operator" aria-label="Filter operator">${operators.map(([v,l])=>option(v,l,v===f.operator)).join('')}</select><input class="filter-value" aria-label="Filter value" value="${esc(f.value)}" placeholder="Value"><button type="button" data-action="remove-filter" aria-label="Remove condition">×</button></div>`;}
function reportModal(existing){
 const draft=existing||defaultReport(),isSaved=state.reports.some(r=>r.id===draft.id),fields=['$task','$sheet',...sourceFields()],cols=draft.columns||['$task','$sheet','Status','Owner','Due'];
 modal(isSaved?'Configure report':'Create report',`<div class="builder-section">${field('Report name','name',existing?.name||'','text','required maxlength="100" placeholder="e.g. Weekly team priorities"')}${field('Description','description',draft.description||'')}</div><div class="builder-section"><h3>1. Choose your sources</h3>${sourceChecks(draft.sheetIds)}</div><div class="builder-section"><h3>2. Narrow the focus</h3>${selectField('Match','match',[{value:'all',label:'All conditions (AND)'},{value:'any',label:'Any condition (OR)'}],draft.match||'all')}<div id="filter-rows">${(draft.filters||(draft.equals?[{column:draft.column,operator:'equals',value:draft.equals}]:[])).map(filterRow).join('')}</div>${button(icon('plus',14)+' Add condition','add-filter','','text-button')}</div><div class="builder-section"><h3>3. Shape the view</h3><div class="column-checks">${fields.map(c=>`<label class="check-field"><input name="col-${esc(c)}" type="checkbox" ${cols.includes(c)?'checked':''}>${esc(c==='$task'?'Item':c==='$sheet'?'Source sheet':c)}</label>`).join('')}</div><div class="form-two">${selectField('Group by','groupBy',[{value:'',label:'No grouping'},...fields.map(c=>({value:c,label:c==='$sheet'?'Source sheet':c==='$task'?'Item':c}))],draft.groupBy||'')}${selectField('Sort by','sortBy',[{value:'',label:'Source row order'},...fields.map(c=>({value:c,label:c==='$sheet'?'Source sheet':c==='$task'?'Item':c}))],draft.sortBy||'')}${selectField('Sort direction','sortDirection',[{value:'asc',label:'Ascending'},{value:'desc',label:'Descending'}],draft.sortDirection||'asc')}</div><label class="check-field"><input type="checkbox" name="leafOnly" ${draft.leafOnly?'checked':''}>Exclude parent rows</label></div>`,async f=>{
 const sheetIds=currentSheets().filter(s=>f['source-'+s.id]).map(s=>s.id),columns=fields.filter(c=>f['col-'+c]);if(!sheetIds.length)throw Error('Choose at least one source sheet.');if(!columns.length)throw Error('Choose at least one visible column.');
 const filters=[...dialog.querySelectorAll('.filter-builder-row')].map(el=>({column:el.querySelector('.filter-column').value,operator:el.querySelector('.filter-operator').value,value:el.querySelector('.filter-value').value}));
 const report={id:isSaved?draft.id:uid(),workspaceId,name:f.name.trim(),description:f.description,sheetIds,columns,filters,match:f.match,groupBy:f.groupBy,sortBy:f.sortBy,sortDirection:f.sortDirection,leafOnly:!!f.leafOnly};
 const ok=await mutate('Saved report: '+report.name,n=>{const index=n.reports.findIndex(r=>r.id===report.id);if(index>=0)n.reports[index]=report;else n.reports.push(report);});if(ok){reportId=report.id;transientReport=null;page='reports';render();}return ok;
 },isSaved?'Save report':'Create report');dialog.classList.add('wide-dialog');
}

function defaultDashboard(s){return {id:s?'sheet-'+s.id:'workspace-overview',workspaceId,name:s?s.name+' overview':'Workspace overview',description:'Every moving piece. One clear picture.',sheetIds:s?[s.id]:currentSheets().map(s=>s.id),statusColumn:'Status',dateColumn:'Due',ownerColumn:'Owner',metricColumn:'Budget',metricFormat:'currency',leafOnly:true,panels:['status','owners','schedule','items']};}
function activeDashboard(){if(dashboardId==='workspace-overview')return defaultDashboard();return state.dashboards.find(d=>d.id===dashboardId)||state.dashboards.find(d=>d.workspaceId===workspaceId)||defaultDashboard();}
function dashboard(s){return dashboardCanvas(defaultDashboard(s),true);}
function dashboardsPage(){const d=activeDashboard(),saved=state.dashboards.filter(d=>d.workspaceId===workspaceId);return pageHeader('THE BIG PICTURE','Dashboards','A calmer way to keep everything in view.',button(icon('plus',15)+' New dashboard','new-dashboard','','primary'))+`<div class="dashboard-switcher"><div class="dashboard-tabs">${[defaultDashboard(),...saved].map(x=>`<button data-action="select-dashboard" data-id="${x.id}" class="${x.id===d.id?'selected':''}">${icon('dashboards',16)}${esc(x.name)}</button>`).join('')}</div>${button(icon('settings',16)+' Configure','configure-dashboard')}</div>`+dashboardCanvas(d);}
function dashboardCanvas(d,compact=false){
 const entries=entriesFor(state,d.sheetIds,{leafOnly:d.leafOnly}),sum=summarize(entries,d),statuses=distribution(entries,d.statusColumn),owners=distribution(entries,d.ownerColumn),maxOwner=Math.max(1,...owners.map(x=>x.count)),panels=d.panels||['status','owners','schedule','items'];
 const upcoming=entries.filter(e=>valueOf(e,d.dateColumn)&&!['complete','done','closed','completed'].includes(String(valueOf(e,d.statusColumn)).toLowerCase())).sort((a,b)=>String(valueOf(a,d.dateColumn)).localeCompare(String(valueOf(b,d.dateColumn)))).slice(0,7);
 const money=d.metricFormat==='currency'?new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(sum.sum):fmt(sum.sum);
 const dateStart=new Date(today()+'T12:00:00');const bins=Array.from({length:6},(_,i)=>{const start=new Date(dateStart);start.setDate(start.getDate()+i*7);const end=new Date(start);end.setDate(end.getDate()+7);return {label:start.toLocaleDateString(undefined,{month:'short',day:'numeric'}),count:entries.filter(e=>{const v=Date.parse(valueOf(e,d.dateColumn));return v>=new Date(start.toISOString().slice(0,10))&&v<new Date(end.toISOString().slice(0,10));}).length};});const maxBin=Math.max(1,...bins.map(b=>b.count));
 return `<div class="dashboard-canvas ${compact?'compact-dashboard':''}">${compact?'':`<div class="dashboard-intro"><div><span class="eyebrow">LIVE WORKSPACE DATA</span><h2>${esc(d.name)}</h2><p>${esc(d.description)}</p></div><span class="dashboard-live">${icon('activity',14)} ${d.sheetIds.length} connected sheet${d.sheetIds.length===1?'':'s'}</span></div>`}
 <div class="insight-metrics">${[['Items in scope',sum.total,'Across selected sheets','sheet'],['Completion',sum.completion+'%',`${sum.complete} complete · ${sum.open} remaining`,'check'],['Needs attention',sum.overdue,'Open items past their due date','activity'],[d.metricColumn||'Total',money,d.leafOnly?'Parent rows excluded':'All rows included','reports']].map(([l,v,n,i])=>`<article class="insight-metric"><div><span>${esc(l)}</span>${icon(i,17)}</div><strong>${v}</strong><p>${esc(n)}</p>${l==='Completion'?`<div class="mini-progress"><span style="width:${sum.completion}%"></span></div>`:''}</article>`).join('')}</div>
 <div class="insight-grid">${panels.includes('status')?`<section class="insight-panel status-panel"><div class="panel-heading"><div><h3>Progress, at a glance</h3><p>How the work is moving.</p></div>${icon('more',18)}</div><div class="status-visual"><div class="donut" style="background:${statusGradient(statuses,sum.total)}"><div><strong>${sum.completion}<small>%</small></strong><span>complete</span></div></div><div class="status-legend">${statuses.map((x,i)=>`<div><span class="legend-dot" style="background:${monochrome[i%monochrome.length]}"></span><span>${esc(x.name)}</span><strong>${x.count}</strong><small>${sum.total?Math.round(x.count/sum.total*100):0}%</small></div>`).join('')||'<p>No items yet.</p>'}</div></div><div class="panel-foot">${sum.total} items · ${d.leafOnly?'Leaf rows only':'Includes parent rows'}</div></section>`:''}
 ${panels.includes('owners')?`<section class="insight-panel owners-panel"><div class="panel-heading"><div><h3>Workload</h3><p>Items by ${esc(d.ownerColumn||'owner')}.</p></div>${icon('user',18)}</div><div class="owner-bars">${owners.slice(0,6).map((x,i)=>`<div class="owner-bar"><div><span class="mini-avatar">${esc(x.name.slice(0,2).toUpperCase())}</span><span>${esc(x.name)}</span><strong>${x.count}</strong></div><div class="bar-track"><span style="width:${x.count/maxOwner*100}%;opacity:${1-i*.1}"></span></div></div>`).join('')||'<p>No assigned work.</p>'}</div>${owners.length>6?`<small>Showing 6 of ${owners.length} owners.</small>`:''}</section>`:''}
 ${panels.includes('schedule')?`<section class="insight-panel schedule-panel"><div class="panel-heading"><div><h3>On the horizon</h3><p>Items due over the next six weeks.</p></div><span class="subtle-pill">${esc(d.dateColumn)}</span></div><div class="column-chart">${bins.map(b=>`<div class="chart-column"><strong>${b.count}</strong><div class="chart-well"><span style="height:${b.count/maxBin*100}%"></span></div><span>${b.label}</span></div>`).join('')}</div></section>`:''}
 ${panels.includes('items')?`<section class="insight-panel items-panel"><div class="panel-heading"><div><h3>Next up</h3><p>The next open items, ordered by due date.</p></div>${button('View all '+icon('arrow',14),'dashboard-report',`data-dashboard="${esc(d.id)}"`,'text-button')}</div><div class="next-items">${upcoming.map(e=>`<button class="next-item" data-action="report-row" data-sheet="${e.sheetId}" data-id="${e.rowId}"><span class="item-marker">${icon('sheet',15)}</span><span class="next-item-title"><b>${esc(e.title)}</b><small>${esc(e.sheetName)} · ${esc(valueOf(e,d.ownerColumn)||'Unassigned')}</small></span><span class="due-label ${String(valueOf(e,d.dateColumn))<today()?'late':''}">${relativeDate(valueOf(e,d.dateColumn))}</span>${icon('arrow',14)}</button>`).join('')||'<div class="quiet-empty">All clear. Add dates to see upcoming work.</div>'}</div></section>`:''}</div>
 <div class="dashboard-foot">${icon('link',14)} Calculated from your sheets. Changes stay connected.${!compact&&state.dashboards.some(x=>x.id===d.id)?button('Delete dashboard','delete-dashboard',`data-id="${d.id}"`,'text-button'):''}</div></div>`;
}
function dashboardModal(existing){const d=existing||defaultDashboard(),isSaved=state.dashboards.some(x=>x.id===d.id),fields=sourceFields();modal(isSaved?'Configure dashboard':'Create dashboard',field('Dashboard name','name',existing?.name||'','text','required placeholder="e.g. Team command center"')+field('Description','description',d.description)+`<div class="builder-section"><h3>Connected sheets</h3>${sourceChecks(d.sheetIds)}</div><div class="form-two">${[['Status field','statusColumn'],['Due date field','dateColumn'],['Owner field','ownerColumn'],['Total field','metricColumn']].map(([label,key])=>selectField(label,key,fields,d[key])).join('')}${selectField('Total display','metricFormat',[{value:'currency',label:'Currency (USD)'},{value:'number',label:'Number'}],d.metricFormat||'currency')}</div><label class="check-field"><input name="leafOnly" type="checkbox" ${d.leafOnly?'checked':''}>Exclude parent rows to avoid double-counting</label><div class="builder-section"><h3>Dashboard panels</h3><div class="column-checks">${[['status','Progress'],['owners','Workload'],['schedule','Due date chart'],['items','Upcoming items']].map(([key,label])=>`<label class="check-field"><input name="panel-${key}" type="checkbox" ${(d.panels||[]).includes(key)?'checked':''}>${label}</label>`).join('')}</div></div>`,async f=>{const sheetIds=currentSheets().filter(s=>f['source-'+s.id]).map(s=>s.id);if(!sheetIds.length)throw Error('Choose at least one sheet.');const dash={...d,id:isSaved?d.id:uid(),workspaceId,name:f.name.trim(),description:f.description,sheetIds,statusColumn:f.statusColumn,dateColumn:f.dateColumn,ownerColumn:f.ownerColumn,metricColumn:f.metricColumn,metricFormat:f.metricFormat,leafOnly:!!f.leafOnly,panels:['status','owners','schedule','items'].filter(k=>f['panel-'+k])};const ok=await mutate('Saved dashboard: '+dash.name,n=>{n.dashboards||=[];const i=n.dashboards.findIndex(x=>x.id===dash.id);if(i<0)n.dashboards.push(dash);else n.dashboards[i]=dash;});if(ok){dashboardId=dash.id;page='dashboards';render();}return ok;},isSaved?'Save dashboard':'Create dashboard');dialog.classList.add('wide-dialog');}

function homePage(){const ss=currentSheets(),entries=entriesFor(state,ss.map(s=>s.id),{leafOnly:true}),sum=summarize(entries);return pageHeader('YOUR WORKSPACE','A little more clarity.','Everything your team is working on, together in one place.',button(icon('plus',15)+' Create sheet','new-sheet','','primary'))+`<div class="home-content"><div class="home-summary"><div><strong>${ss.length}</strong><span>Sheets</span></div><div><strong>${sum.open}</strong><span>Open items</span></div><div><strong>${sum.completion}%</strong><span>Complete</span></div><div><strong>${state.reports.filter(r=>r.workspaceId===workspaceId).length}</strong><span>Saved reports</span></div></div><div class="section-title"><h2>Your sheets</h2><span>${button(icon('download',14)+' Import','import','','text-button')}${button(icon('plus',14)+' New workspace','new-workspace','','text-button')}</span></div><div class="sheet-cards">${ss.map(s=>{const e=entriesFor(state,[s.id],{leafOnly:true}),m=summarize(e);return `<button class="sheet-card" data-action="sheet" data-id="${s.id}"><div class="sheet-card-top"><span class="sheet-card-icon">${icon('sheet',23)}</span>${icon('arrow',18)}</div><h3>${esc(s.name)}</h3><p>${esc(s.description||'A place for every detail.')}</p><div class="card-progress"><span style="width:${m.completion}%"></span></div><footer><span>${s.rows.length} rows</span><span>${m.completion}% complete</span></footer></button>`;}).join('')}<button class="sheet-card new-card" data-action="new-sheet"><span class="new-card-plus">${icon('plus',24)}</span><h3>Make room for what’s next.</h3><p>Start with a project template or a blank sheet.</p></button></div><div class="home-bottom"><button class="home-feature" data-action="page" data-page="reports">${icon('reports',25)}<div><h3>See beyond a single sheet.</h3><p>Build a report that brings the right work together.</p></div>${icon('arrow',18)}</button><button class="home-feature" data-action="page" data-page="dashboards">${icon('dashboards',25)}<div><h3>Less noise. More insight.</h3><p>Build a dashboard around what matters.</p></div>${icon('arrow',18)}</button></div></div>`;}

const testChecks=[['sheet','Create a sheet and add typed columns'],['edit','Edit cells and confirm they persist after reload'],['formula','Use a formula and verify recalculation'],['views','Switch between table, board, and calendar'],['report','Build a grouped report with conditions'],['dashboard','Create a dashboard with field mappings'],['form','Submit a form and find the new row'],['automation','Trigger a cell-change automation'],['backup','Export a project backup'],['tabs','Open two tabs and verify change notifications']];
function testingPage(){const feedback=state.feedback||[],checks=state.testing||{},done=testChecks.filter(([k])=>checks[k]).length;return pageHeader('MAKE IT BETTER, TOGETHER','Test lab','A place for your team’s observations, ideas, and rough edges.',button(icon('plus',15)+' Leave feedback','new-feedback','','primary'))+`<div class="test-layout"><section class="insight-panel test-checklist"><div class="panel-heading"><div><h3>A good first run</h3><p>${done} of ${testChecks.length} checks complete</p></div><span class="subtle-pill">${Math.round(done/testChecks.length*100)}%</span></div><div class="checklist-progress"><span style="width:${done/testChecks.length*100}%"></span></div>${testChecks.map(([key,label])=>`<label class="test-check"><input type="checkbox" data-test-check="${key}" ${checks[key]?'checked':''}><span>${label}${checks[key]?`<small>Checked by ${esc(checks[key].by)}</small>`:''}</span></label>`).join('')}<div class="testing-note">This is a local test workspace on this Mac. Tester names label feedback; they are not accounts or access permissions.</div></section><section class="feedback-list"><div class="section-title"><h2>Team feedback</h2><span>${feedback.filter(f=>f.status!=='Resolved').length} open</span></div>${[...feedback].reverse().map(f=>`<article class="feedback-card"><div class="feedback-meta"><span class="subtle-pill">${esc(f.kind)}</span><span>${esc(f.area)}</span><span>${new Date(f.at).toLocaleDateString()}</span></div><h3>${esc(f.title)}</h3><p>${esc(f.description)}</p>${f.steps?`<details><summary>Steps to reproduce</summary><p>${esc(f.steps)}</p></details>`:''}<footer><span class="mini-avatar">${esc(f.by.slice(0,2).toUpperCase())}</span><span>${esc(f.by)}</span><select data-feedback-status="${f.id}" aria-label="Status of ${esc(f.title)}">${['Open','In progress','Resolved'].map(s=>option(s,s,s===f.status)).join('')}</select></footer></article>`).join('')||`<div class="feedback-empty">${icon('testing',32)}<h3>Fresh eyes welcome.</h3><p>Something confusing? Something missing?<br>Capture it here so it doesn’t get lost.</p>${button('Leave the first note','new-feedback')}</div>`}</section></div>`;}

